// Deterministic reconciliation. Everything below is arithmetic and format
// checking - no model opinion is involved in deciding whether an invoice is sound.
const req = $('Normalise Document Request').first().json;
const src = $json;

const exceptions = [];
function ex(code, severity, detail) { exceptions.push({ code: code, severity: severity, detail: detail }); }

function num(v) {
  if (v === null || v === undefined || v === '') { return null; }
  if (typeof v === 'number') { return isFinite(v) ? v : null; }
  const cleaned = String(v).replace(/[^0-9.,\-]/g, '').replace(/,(?=\d{3}\b)/g, '').replace(',', '.');
  const n = Number(cleaned);
  return isFinite(n) ? n : null;
}

let inv = null;
let parseError = null;
const raw = String(src.extraction_raw || '').replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
if (!raw) {
  parseError = src.model_error ? ('extraction step failed: ' + src.model_error) : 'extraction produced no output';
} else {
  try { inv = JSON.parse(raw); } catch (e) { parseError = 'extraction is not valid JSON: ' + String(e.message || e); }
}
if (parseError) { ex('extraction_failed', 'critical', parseError); }
if (!inv || typeof inv !== 'object') { inv = {}; }

// ---- Document type ------------------------------------------------------
const SUPPORTED = ['invoice', 'credit_note', 'receipt'];
const docType = String(inv.document_type || 'invoice').toLowerCase();
if (SUPPORTED.indexOf(docType) === -1) {
  ex('unsupported_document_type', 'critical', 'document_type "' + docType + '" is not one of ' + SUPPORTED.join(', '));
}

// ---- Required fields ----------------------------------------------------
const REQUIRED = ['invoice_number', 'vendor_name', 'invoice_date', 'currency', 'total'];
const missing = REQUIRED.filter(function (f) {
  const v = inv[f];
  return v === null || v === undefined || String(v).trim() === '';
});
missing.forEach(function (f) { ex('missing_required_field', 'critical', f); });

// ---- Currency -----------------------------------------------------------
const currency = String(inv.currency || '').toUpperCase().trim();
if (currency && !/^[A-Z]{3}$/.test(currency)) {
  ex('invalid_currency', 'high', 'currency "' + inv.currency + '" is not a three-letter ISO 4217 code');
}

// ---- Dates --------------------------------------------------------------
const ISO = /^\d{4}-\d{2}-\d{2}$/;
const invDate = inv.invoice_date ? String(inv.invoice_date) : null;
const dueDate = inv.due_date ? String(inv.due_date) : null;
if (invDate && !ISO.test(invDate)) {
  ex('invalid_date', 'high', 'invoice_date "' + invDate + '" is not ISO YYYY-MM-DD');
} else if (invDate) {
  const d = new Date(invDate + 'T00:00:00Z');
  if (isNaN(d.getTime())) { ex('invalid_date', 'high', 'invoice_date "' + invDate + '" is not a real date'); }
  else if (d.getTime() > Date.now() + 86400000) { ex('future_dated', 'medium', 'invoice_date ' + invDate + ' is in the future'); }
}
if (dueDate && ISO.test(dueDate) && invDate && ISO.test(invDate) && dueDate < invDate) {
  ex('due_before_invoice_date', 'high', 'due_date ' + dueDate + ' precedes invoice_date ' + invDate);
}

// ---- Arithmetic ---------------------------------------------------------
const TOL = 0.02;
const subtotal = num(inv.subtotal);
const tax = num(inv.tax);
const total = num(inv.total);
const items = Array.isArray(inv.line_items) ? inv.line_items : [];

let lineSum = null;
if (items.length) {
  let sum = 0;
  let usable = true;
  items.forEach(function (li, i) {
    const amount = num(li.amount);
    const qty = num(li.quantity);
    const unit = num(li.unit_price);
    if (amount !== null) {
      sum += amount;
      if (qty !== null && unit !== null && Math.abs(qty * unit - amount) > TOL) {
        ex('line_item_arithmetic', 'high', 'line ' + (i + 1) + ': quantity ' + qty + ' x unit ' + unit + ' = ' + (qty * unit).toFixed(2) + ' but amount is ' + amount);
      }
    } else if (qty !== null && unit !== null) {
      sum += qty * unit;
    } else {
      usable = false;
    }
    if (amount !== null && amount < 0 && docType !== 'credit_note') {
      ex('negative_line_amount', 'high', 'line ' + (i + 1) + ' has a negative amount on a ' + docType);
    }
  });
  lineSum = usable ? Math.round(sum * 100) / 100 : null;
  if (!usable) { ex('line_items_unparseable', 'medium', 'at least one line item has neither an amount nor quantity and unit price'); }
}

if (lineSum !== null && subtotal !== null && Math.abs(lineSum - subtotal) > TOL) {
  ex('line_items_do_not_sum', 'critical', 'line items total ' + lineSum.toFixed(2) + ' but subtotal is ' + subtotal.toFixed(2));
}
if (subtotal !== null && tax !== null && total !== null && Math.abs((subtotal + tax) - total) > TOL) {
  ex('totals_mismatch', 'critical', 'subtotal ' + subtotal.toFixed(2) + ' + tax ' + tax.toFixed(2) + ' = ' + (subtotal + tax).toFixed(2) + ' but total is ' + total.toFixed(2));
}
if (total !== null && total < 0 && docType !== 'credit_note') {
  ex('negative_total', 'high', 'total ' + total + ' is negative on a ' + docType);
}
if (tax !== null && subtotal !== null && subtotal > 0) {
  const rate = tax / subtotal;
  if (rate > 0.6) { ex('implausible_tax_rate', 'medium', 'implied tax rate is ' + Math.round(rate * 100) + ' percent'); }
}

// ---- Model confidence ---------------------------------------------------
const confidence = typeof inv.confidence === 'number' ? inv.confidence : null;
const floor = Number(req.confidence_floor || 0.7);
if (confidence === null) { ex('confidence_not_reported', 'medium', 'the extractor did not report a confidence value'); }
else if (confidence < floor) { ex('low_confidence', 'high', 'reported confidence ' + confidence + ' is below the floor of ' + floor); }

// ---- Fingerprint for duplicate detection --------------------------------
function normKey(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]/g, ''); }
const fingerprint = [
  normKey(inv.vendor_name),
  normKey(inv.invoice_number),
  currency,
  total === null ? 'na' : total.toFixed(2)
].join('|');

const normalised = {
  document_type: docType,
  invoice_number: inv.invoice_number || null,
  vendor_name: inv.vendor_name || null,
  customer_name: inv.customer_name || null,
  invoice_date: invDate,
  due_date: dueDate,
  currency: currency || null,
  line_items: items,
  line_item_count: items.length,
  line_item_sum: lineSum,
  subtotal: subtotal,
  tax: tax,
  total: total,
  payment_terms: inv.payment_terms || null,
  confidence: confidence,
  notes: Array.isArray(inv.notes) ? inv.notes : []
};

return {
  json: {
    document_ref: req.document_ref,
    source_workflow: req.source_workflow,
    started_at_ms: req.started_at_ms,
    confidence_floor: floor,
    extraction_source: src.extraction_source,
    model: { provider: src.model_provider || null, latency_ms: src.model_latency_ms || 0, estimated_cost_usd: src.model_cost_usd || 0 },
    invoice: normalised,
    invoice_json: JSON.stringify(normalised),
    fingerprint: fingerprint,
    exceptions: exceptions,
    parse_error: parseError
  }
};

// Folds the duplicate-ledger lookup into the exception list and computes a
// system confidence that is independent of what the model claimed about itself.
const base = $('Validate and Reconcile').first().json;
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.fingerprint; });

const exceptions = (base.exceptions || []).slice();
const prior = rows[0] || null;
if (prior) {
  exceptions.push({
    code: 'duplicate_invoice', severity: 'critical',
    detail: 'fingerprint already recorded on ' + (prior.first_seen_at || 'an earlier run') +
      ' (ledger row ' + prior.id + ', execution ' + (prior.execution_id || 'unknown') + ')'
  });
}

const critical = exceptions.filter(function (e) { return e.severity === 'critical'; });
const high = exceptions.filter(function (e) { return e.severity === 'high'; });
const medium = exceptions.filter(function (e) { return e.severity === 'medium'; });

// System confidence starts at 1 and is reduced by evidence, never raised by it.
let confidence = 1;
confidence -= critical.length * 0.5;
confidence -= high.length * 0.2;
confidence -= medium.length * 0.05;
const modelConf = base.invoice && typeof base.invoice.confidence === 'number' ? base.invoice.confidence : null;
if (modelConf !== null) { confidence = Math.min(confidence, 0.5 + 0.5 * modelConf); }
confidence = Math.max(0, Math.round(confidence * 100) / 100);

const status = critical.length ? 'rejected' : (high.length || medium.length ? 'needs_review' : 'accepted');

return [{
  json: Object.assign({}, base, {
    exceptions: exceptions,
    exception_counts: { critical: critical.length, high: high.length, medium: medium.length, total: exceptions.length },
    is_duplicate: !!prior,
    duplicate_of: prior ? { ledger_row: prior.id, first_seen_at: prior.first_seen_at, execution_id: prior.execution_id } : null,
    system_confidence: confidence,
    status: status,
    needs_human_review: status !== 'accepted'
  })
}];

const a = $('Assess Exceptions').first().json;

function unwrap(n) {
  try { const v = $(n).first().json; return (v && v.json) ? v.json : v; } catch (e) { return null; }
}
const verification = unwrap('Verify Extraction (09)');

let governance = null;
try { governance = $('Escalate to Governance (05)').first().json; } catch (e) { governance = null; }
if (governance && governance.json) { governance = governance.json; }
if (!governance) { try { governance = $('Clean, No Review Needed').first().json; } catch (e) { governance = null; } }

return [{
  json: {
    document_ref: a.document_ref,
    n8n_execution_id: $execution.id,
    status: a.status,
    accepted: a.status === 'accepted',
    system_confidence: a.system_confidence,
    invoice: a.invoice,
    fingerprint: a.fingerprint,
    is_duplicate: a.is_duplicate,
    duplicate_of: a.duplicate_of,
    exceptions: a.exceptions,
    exception_counts: a.exception_counts,
    extraction_source: a.extraction_source,
    model: a.model,
    verification: verification ? { verified: verification.verified, score: verification.score, issues: verification.issues } : null,
    review: governance ? { decision: governance.decision, approved: !!governance.approved, risk_level: governance.risk_level, reason: governance.decision_reason } : null,
    latency_ms: a.started_at_ms ? (Date.now() - Number(a.started_at_ms)) : null
  }
}];

// Invoice fixtures. Every vendor, number and amount below is invented; no real
// financial or customer data appears anywhere in this repository.
//
// Most cases supply extraction_override so the reconciliation logic is exercised
// deterministically, without model variance. I12 goes through the real model path.
//
// The vendor name is scoped to this execution so that I01 inserts a fresh ledger
// row and I07 duplicates it, without colliding with rows left by earlier runs.
const RUN = 'R' + $execution.id;
const VENDOR = 'Northwind Traders ' + RUN;

function inv(o) {
  return JSON.stringify(Object.assign({
    document_type: 'invoice',
    invoice_number: 'INV-1000',
    vendor_name: VENDOR,
    customer_name: 'Acme Supplies Pty Ltd',
    invoice_date: '2026-08-14',
    due_date: '2026-09-13',
    currency: 'EUR',
    line_items: [{ description: 'Widget A', quantity: 10, unit_price: 80, amount: 800 }, { description: 'Widget B', quantity: 4, unit_price: 50, amount: 200 }],
    subtotal: 1000,
    tax: 240.5,
    total: 1240.5,
    payment_terms: 'Net 30',
    confidence: 0.94,
    notes: []
  }, o));
}

const F = [
  { case_id: 'I01-clean-invoice', expect_status: 'accepted', expect_codes: [],
    extraction_override: inv({}) },
  { case_id: 'I02-totals-mismatch', expect_status: 'rejected', expect_codes: ['totals_mismatch'],
    extraction_override: inv({ invoice_number: 'INV-1002', total: 1300 }) },
  { case_id: 'I03-missing-vendor', expect_status: 'rejected', expect_codes: ['missing_required_field'],
    extraction_override: inv({ invoice_number: 'INV-1003', vendor_name: null }) },
  { case_id: 'I04-line-items-do-not-sum', expect_status: 'rejected', expect_codes: ['line_items_do_not_sum'],
    extraction_override: inv({ invoice_number: 'INV-1004', line_items: [{ description: 'Widget A', quantity: 10, unit_price: 80, amount: 800 }] }) },
  { case_id: 'I05-low-confidence', expect_status: 'needs_review', expect_codes: ['low_confidence'],
    extraction_override: inv({ invoice_number: 'INV-1005', confidence: 0.42 }) },
  { case_id: 'I06-unsupported-document-type', expect_status: 'rejected', expect_codes: ['unsupported_document_type'],
    extraction_override: inv({ invoice_number: 'INV-1006', document_type: 'contract' }) },
  { case_id: 'I07-duplicate-of-I01', expect_status: 'rejected', expect_codes: ['duplicate_invoice'],
    extraction_override: inv({}) },
  { case_id: 'I08-malformed-extraction', expect_status: 'rejected', expect_codes: ['extraction_failed'],
    extraction_override: '{"invoice_number": "INV-1008", "total": ' },
  { case_id: 'I09-invalid-date', expect_status: 'needs_review', expect_codes: ['invalid_date'],
    extraction_override: inv({ invoice_number: 'INV-1009', invoice_date: '13/45/2026', due_date: null }) },
  { case_id: 'I10-invalid-currency', expect_status: 'needs_review', expect_codes: ['invalid_currency'],
    extraction_override: inv({ invoice_number: 'INV-1010', currency: 'EURO' }) },
  { case_id: 'I11-future-dated', expect_status: 'needs_review', expect_codes: ['future_dated'],
    extraction_override: inv({ invoice_number: 'INV-1011', invoice_date: '2099-01-01', due_date: null }) },
  { case_id: 'I12-real-model-extraction', expect_status: null, expect_codes: [], expect_model_path: true,
    extraction_override: '',
    document_text: 'INVOICE\n\nAcme Supplies Pty Ltd\n17 Harbour Road, Adelaide SA 5000\n\nInvoice number: INV-7781\nInvoice date: 2026-08-02\nDue date: 2026-09-01\nVendor: Blue Harbour Logistics ' + RUN + '\n\nDescription                Qty   Unit price   Amount\nPallet freight             3     120.00       360.00\nHandling surcharge         1      45.00        45.00\n\nSubtotal        405.00\nGST 10%          40.50\nTotal EUR       445.50\n\nPayment terms: Net 30' }
];

return F.map(function (f) {
  return { json: {
    case_id: f.case_id,
    expect_status: f.expect_status,
    expect_codes: f.expect_codes || [],
    expect_model_path: !!f.expect_model_path,
    document_text: f.document_text || ('Fixture ' + f.case_id + ' supplies a pre-parsed extraction, so no document text is needed.'),
    document_ref: 'test-' + $execution.id + '-' + f.case_id,
    extraction_override: f.extraction_override,
    confidence_floor: '0.7',
    source_workflow: '06-test-suite::' + f.case_id
  } };
});

const fixtures = $('Build Invoice Fixtures').all().map(function (i) { return i.json; });
const results = $input.all().map(function (i) { return i.json; });

const rows = results.map(function (r, idx) {
  const fx = fixtures[idx] || {};
  const fails = [];
  if (fx.expect_status && r.status !== fx.expect_status) {
    fails.push('expected status ' + fx.expect_status + ' but got ' + r.status);
  }
  (fx.expect_codes || []).forEach(function (c) {
    if ((r.codes || []).indexOf(c) === -1) { fails.push('expected exception code ' + c + ' was not raised'); }
  });
  if (fx.expect_model_path) {
    if (r.extraction_source !== 'model') { fails.push('expected the real model extraction path, got ' + r.extraction_source); }
    if (!r.invoice_number) { fails.push('model extraction produced no invoice_number'); }
  }
  return {
    case_id: fx.case_id, pass: fails.length === 0,
    expected_status: fx.expect_status, actual_status: r.status,
    expected_codes: fx.expect_codes, actual_codes: r.codes,
    system_confidence: r.system_confidence,
    invoice_number: r.invoice_number, total: r.total,
    extraction_source: r.extraction_source, model_provider: r.model_provider,
    verification_verified: r.verification_verified, review_decision: r.review_decision,
    exception_details: r.exception_details,
    fail_reasons: fails, latency_ms_measured: r.latency_ms
  };
});

const passed = rows.filter(function (r) { return r.pass; }).length;
const deterministic = rows.filter(function (r) { return r.extraction_source === 'supplied'; });
const lats = deterministic.map(function (r) { return r.latency_ms_measured; }).filter(function (v) { return typeof v === 'number'; }).sort(function (a, b) { return a - b; });
const modelRuns = rows.filter(function (r) { return r.extraction_source === 'model'; });

return [{ json: {
  suite: 'invoice-fixtures-v1', generated_at: new Date().toISOString(), n8n_execution_id: $execution.id,
  note: 'Eleven cases supply a pre-parsed extraction so the reconciliation, duplicate and exception logic is exercised without model variance. I12 runs the real extraction path through the Model Router. All vendor names, invoice numbers and amounts are invented.',
  total: rows.length, passed: passed, failed: rows.length - passed, all_passed: passed === rows.length,
  deterministic_latency_ms_p50_measured: lats.length ? lats[Math.max(0, Math.ceil(0.5 * lats.length) - 1)] : null,
  deterministic_latency_ms_max_measured: lats.length ? lats[lats.length - 1] : null,
  model_path_latency_ms_measured: modelRuns.length ? modelRuns[0].latency_ms_measured : null,
  cases: rows
} }];

