    extraction_source: src.extraction_source,
    model: { provider: src.model_provider || null, latency_ms: src.model_latency_ms || 0, estimated_cost_usd: src.model_cost_usd || 0 },
    invoice: normalised,
    invoice_json: JSON.stringify(normalised),
    fingerprint: fingerprint,
    exceptions: exceptions,
    parse_error: parseError
  }
};

// Folds the duplicate-ledger lookup into the exception list and computes a
// system confidence that is independent of what the model claimed about itself.
const base = $('Validate and Reconcile').first().json;
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.fingerprint; });

const exceptions = (base.exceptions || []).slice();
const prior = rows[0] || null;
if (prior) {
  exceptions.push({
    code: 'duplicate_invoice', severity: 'critical',
    detail: 'fingerprint already recorded on ' + (prior.first_seen_at || 'an earlier run') +
      ' (ledger row ' + prior.id + ', execution ' + (prior.execution_id || 'unknown') + ')'
  });
}

const critical = exceptions.filter(function (e) { return e.severity === 'critical'; });
const high = exceptions.filter(function (e) { return e.severity === 'high'; });
const medium = exceptions.filter(function (e) { return e.severity === 'medium'; });

// System confidence starts at 1 and is reduced by evidence, never raised by it.
let confidence = 1;
confidence -= critical.length * 0.5;
confidence -= high.length * 0.2;
confidence -= medium.length * 0.05;
const modelConf = base.invoice && typeof base.invoice.confidence === 'number' ? base.invoice.confidence : null;
if (modelConf !== null) { confidence = Math.min(confidence, 0.5 + 0.5 * modelConf); }
confidence = Math.max(0, Math.round(confidence * 100) / 100);

const status = critical.length ? 'rejected' : (high.length || medium.length ? 'needs_review' : 'accepted');

return [{
  json: Object.assign({}, base, {
    exceptions: exceptions,
    exception_counts: { critical: critical.length, high: high.length, medium: medium.length, total: exceptions.length },
    is_duplicate: !!prior,
    duplicate_of: prior ? { ledger_row: prior.id, first_seen_at: prior.first_seen_at, execution_id: prior.execution_id } : null,
    system_confidence: confidence,
    status: status,
    needs_human_review: status !== 'accepted'
  })
}];

const a = $('Assess Exceptions').first().json;

function unwrap(n) {
  try { const v = $(n).first().json; return (v && v.json) ? v.json : v; } catch (e) { return null; }
}
const verification = unwrap('Verify Extraction (09)');

let governance = null;
try { governance = $('Escalate to Governance (05)').first().json; } catch (e) { governance = null; }
if (governance && governance.json) { governance = governance.json; }
if (!governance) { try { governance = $('Clean, No Review Needed').first().json; } catch (e) { governance = null; } }

return [{
  json: {
    document_ref: a.document_ref,
    n8n_execution_id: $execution.id,
    status: a.status,
    accepted: a.status === 'accepted',
    system_confidence: a.system_confidence,
    invoice: a.invoice,
    fingerprint: a.fingerprint,
    is_duplicate: a.is_duplicate,
    duplicate_of: a.duplicate_of,
    exceptions: a.exceptions,
    exception_counts: a.exception_counts,
    extraction_source: a.extraction_source,
    model: a.model,
    verification: verification ? { verified: verification.verified, score: verification.score, issues: verification.issues } : null,
    review: governance ? { decision: governance.decision, approved: !!governance.approved, risk_level: governance.risk_level, reason: governance.decision_reason } : null,
    latency_ms: a.started_at_ms ? (Date.now() - Number(a.started_at_ms)) : null
  }
}];

// Invoice fixtures. Every vendor, number and amount below is invented; no real
// financial or customer data appears anywhere in this repository.
//
// Most cases supply extraction_override so the reconciliation logic is exercised
// deterministically, without model variance. I12 goes through the real model path.
//
// The vendor name is scoped to this execution so that I01 inserts a fresh ledger
// row and I07 duplicates it, without colliding with rows left by earlier runs.
const RUN = 'R' + $execution.id;
const VENDOR = 'Northwind Traders ' + RUN;

function inv(o) {
