    total: 1240.5,
    payment_terms: 'Net 30',
    confidence: 0.94,
    notes: []
  }, o));
}

const F = [
  { case_id: 'I01-clean-invoice', expect_status: 'accepted', expect_codes: [],
    extraction_override: inv({}) },
  { case_id: 'I02-totals-mismatch', expect_status: 'rejected', expect_codes: ['totals_mismatch'],
